// func compressChunksAVX2(cvs *[8][8]uint32, buf *[8192]byte, key *[8]uint32, counter uint64, flags uint32)
// Requires: AVX, AVX2, MMX+
TEXT ·compressChunksAVX2(SB), NOSPLIT, $704-36
	MOVQ cvs+0(FP), AX
	MOVQ buf+8(FP), CX
	MOVQ key+16(FP), DX
	LEAQ (SP), BX
	ADDQ $0x1f, BX
	ANDQ $-32, BX

	// Load key
	VPBROADCASTD (DX), Y0
	VPBROADCASTD 4(DX), Y1
	VPBROADCASTD 8(DX), Y2
	VPBROADCASTD 12(DX), Y3
	VPBROADCASTD 16(DX), Y4
	VPBROADCASTD 20(DX), Y5
	VPBROADCASTD 24(DX), Y6
	VPBROADCASTD 28(DX), Y7

	// Initialize counter
	VPBROADCASTQ counter+24(FP), Y12
	VPBROADCASTQ counter+24(FP), Y13
	VPADDQ       seq64<>+0(SB), Y12, Y12
	VPADDQ       seq64<>+32(SB), Y13, Y13
	VPUNPCKLDQ   Y13, Y12, Y14
	VPUNPCKHDQ   Y13, Y12, Y15
	VPUNPCKLDQ   Y15, Y14, Y12
	VPUNPCKHDQ   Y15, Y14, Y13
	VPERMQ       $0xd8, Y12, Y12
	VPERMQ       $0xd8, Y13, Y13
	VMOVDQU      Y12, 544(BX)
	VMOVDQU      Y13, 576(BX)

	// Initialize flags
	VPBROADCASTD flags+32(FP), Y14
	VMOVDQU      Y14, 608(BX)
	VMOVDQU      Y14, 640(BX)
	ORL          $0x01, 608(BX)
	ORL          $0x02, 668(BX)

	// Loop index
	XORQ DX, DX

loop:
	// Load transposed block
	VMOVDQU     (CX), X8
	VINSERTI128 $0x01, 4096(CX), Y8, Y8
	VMOVDQU     1024(CX), X9
	VINSERTI128 $0x01, 5120(CX), Y9, Y9
	VMOVDQU     2048(CX), X10
	VINSERTI128 $0x01, 6144(CX), Y10, Y10
	VMOVDQU     3072(CX), X11
	VINSERTI128 $0x01, 7168(CX), Y11, Y11
	VPUNPCKLQDQ Y9, Y8, Y12
	VPUNPCKHQDQ Y9, Y8, Y13
	VPUNPCKLQDQ Y11, Y10, Y14
	VPUNPCKHQDQ Y11, Y10, Y15
	VSHUFPS     $0x88, Y14, Y12, Y8
